content:
:root {
  --primary-color: #ff6b6b;
  --primary-hover: #fa5252;
  --bg-color: #f8f9fa;
  --card-bg: #ffffff;
  --text-color: #343a40;
  --text-secondary: #868e96;
  --border-radius: 16px;
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 480px;
  padding: 20px;
}

.timer-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  padding: 40px 30px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.status-badge {
  background-color: #ffe3e3;
  color: var(--primary-color);
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 24px;
  letter-spacing: 0.5px;
}

.timer-display {
  font-size: 5rem;
  font-weight: 700;
  color: var(--text-color);
  margin-bottom: 30px;
  font-variant-numeric: tabular-nums;
  letter-spacing: -2px;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.btn {
  flex: 1;
  padding: 14px 20px;
  border-radius: 12px;
  border: none;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}

.btn:active {
  transform: translateY(1px);
}

.btn-start {
  background-color: var(--primary-color);
  color: white;
}

.btn-start:hover {
  background-color: var(--primary-hover);
}

.btn-pause {
  background-color: #f1f3f5;
  color: var(--text-color);
}

.btn-pause:hover {
  background-color: #e9ecef;
}

.btn-reset {
  background-color: #f1f3f5;
  color: var(--text-secondary);
}

.btn-reset:hover {
  background-color: #e9ecef;
  color: var(--text-color);
}

import { useState, useEffect } from 'react';

const POMODORO_TIME = 25 * 60; // 25分

export default function App() {
  const [timeLeft, setTimeLeft] = useState<number>(POMODORO_TIME);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [isCompleted, setIsCompleted] = useState<boolean>(false);

  useEffect(() => {
    let interval: number | undefined;

    if (isRunning && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isRunning) {
      setIsRunning(false);
      setIsCompleted(true);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isRunning, timeLeft]);

  const handleStart = () => {
    setIsRunning(true);
    setIsCompleted(false);
  };

  const handlePause = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(POMODORO_TIME);
    setIsCompleted(false);
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  return (
    <div className="app-container">
      <div className="timer-card">
        <div className="status-badge">
          {isCompleted ? '完了しました！お疲れ様です' : isRunning ? '集中タイム' : '準備完了'}
        </div>

        <div className="timer-display">
          {formattedTime}
        </div>

        <div className="controls">
          {!isRunning ? (
            <button className="btn btn-start" onClick={handleStart}>
              開始
            </button>
          ) : (
            <button className="btn btn-pause" onClick={handlePause}>
              一時停止
            </button>
          )}
          <button className="btn btn-reset" onClick={handleReset}>
            リセット
          </button>
        </div>
      </div>
    </div>
  );
}
